CustomField.formula:
IF(MONTH(Fecha_Inicio__c) == 1,
    IF(ISPICKVAL(Tipo_de_Mantencion__c, "Mantencion Mayor"),
        /* Si se exporta, Excel prioriza el texto plano. Si está en SF, muestra el link con la imagen */
        HYPERLINK('/flow/Maintenance_Preview?recordId=' & Id & '&retURL=/' & $Label.Maintenance_Report_Calendar_Id, "MM") & 
        IF(false, IMAGE($Label.Mantencion_Mayor_imagen, "MM", 15, 100), ""),

        HYPERLINK('/flow/Maintenance_Preview?recordId=' & Id & '&retURL=/' & $Label.Maintenance_Report_Calendar_Id, "MS") & 
        IF(false, IMAGE($Label.Mantencion_de_Servicios_Imagen, "MS", 15, 100), "")
    ),
    NULL
)
